   389      // MFT matrices are applied before the first set of curves, but must be identity unless the
   390      // input is PCSXYZ. We don't support PCSXYZ profiles, so we ignore this matrix. Note that the
   391      // matrix in skcms_A2B is applied later in the pipe, so supporting this would require another
   392      // field/flag.
   393      a2b->matrix_channels = 0;
   394
   395      a2b->input_channels  = mftTag->input_channels[0];
   396      for (uint32_t i = 0; i < a2b->input_channels; ++i) {
   397          a2b->grid_points[i] = mftTag->grid_points[0];
   398      }
   399      a2b->output_channels = mftTag->output_channels[0];
   400
   401      // We require exactly three (ie XYZ/Lab/RGB) output channels
   402      if (a2b->output_channels != ARRAY_COUNT(a2b->output_curves)) {
   403          return false;
   404      }
   405      // We require at least one, and no more than four (ie CMYK) input channels
   406      if (a2b->input_channels < 1 || a2b->input_channels > ARRAY_COUNT(a2b->input_curves)) {
   407          return false;
   408      }
   409      // The grid only makes sense with at least two points along each axis
   410      if (a2b->grid_points[0] < 2) {
   411          return false;
   412      }
   413
   414      return true;
